<script setup lang="ts">
type Game={id:string;opponent:{nickname:string};color:'white'|'black';result:'win'|'loss'|'draw';rating_change:number|null;time_control:{label:string};finished_at:string}
defineProps<{games:Game[];title:string}>();defineEmits<{all:[]}>()
function label(v:Game['result']){return v==='win'?'Vitória':v==='loss'?'Derrota':'Empate'}
function date(v:string){return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(v))}
</script>
<template><section class="panel games"><header><h2>{{title}}</h2><button @click="$emit('all')">Ver todas</button></header><p v-if="!games.length" class="empty">Nenhuma partida finalizada.</p><NuxtLink v-for="game in games" :key="game.id" class="game-row" :to="`/game/${game.id}/review`" :aria-label="`Analisar partida contra ${game.opponent.nickname}`"><b :class="game.result">{{label(game.result)}}</b><div><strong>vs {{game.opponent.nickname}}</strong><span>{{game.time_control.label}} · {{game.color==='white'?'Brancas':'Pretas'}}</span></div><em v-if="game.rating_change!==null" :class="{positive:game.rating_change>=0}">{{game.rating_change>=0?'+':''}}{{game.rating_change}}</em><time>{{date(game.finished_at)}}</time></NuxtLink></section></template>
<style scoped>.panel{padding:1.25rem;background:var(--surface);border:1px solid var(--border);border-radius:14px;box-shadow:var(--shadow)}header{display:flex;align-items:center;justify-content:space-between;margin-bottom:.8rem}h2{margin:0;font-size:1.05rem}button{padding:.6rem;color:var(--accent);background:transparent;border:0;font-weight:800;cursor:pointer}.game-row{display:grid;grid-template-columns:76px 1fr auto 100px;align-items:center;gap:.8rem;padding:.8rem 0;color:var(--text);border-top:1px solid var(--border-subtle);text-decoration:none}.game-row div{display:grid}.game-row span,.game-row time{color:var(--text-muted);font-size:.8rem}.game-row b{color:var(--text-muted)}.game-row b.win,.game-row em.positive{color:var(--success)}.game-row b.loss,.game-row em{color:var(--danger)}.game-row b,.game-row strong{transition:color 140ms ease}.game-row:hover b,.game-row:hover strong,.game-row:focus-visible b,.game-row:focus-visible strong{color:var(--accent)!important}.game-row:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.game-row em{font-style:normal;font-weight:800}.empty{color:var(--text-muted);text-align:center}@media(max-width:720px){.game-row{grid-template-columns:68px 1fr auto}.game-row time{display:none}}</style>
